111 #define TracyLfqPrepare( _type ) \
112     moodycamel::ConcurrentQueueDefaultTraits::index_t __magic; \
113     auto __token = GetToken(); \
114     auto& __tail = __token->get_tail_index(); \
115     auto item = __token->enqueue_begin( __magic ); \
116     MemWrite( &item->hdr.type, _type );
117 
118 #define TracyLfqCommit \
119     __tail.store( __magic + 1, std::memory_order_release );
120 
121 #define TracyLfqPrepareC( _type ) \
122     tracy::moodycamel::ConcurrentQueueDefaultTraits::index_t __magic; \
123     auto __token = tracy::GetToken(); \
124     auto& __tail = __token->get_tail_index(); \
125     auto item = __token->enqueue_begin( __magic ); \
126     tracy::MemWrite( &item->hdr.type, _type );
127 
128 #define TracyLfqCommitC \
129     __tail.store( __magic + 1, std::memory_order_release );
130 
