133 #  define TracyQueuePrepare( _type ) \
134     auto item = Profiler::QueueSerial(); \
135     MemWrite( &item->hdr.type, _type );
136 #  define TracyQueueCommit( _name ) \
137     MemWrite( &item->_name.thread, GetThreadHandle() ); \
138     Profiler::QueueSerialFinish();
139 #  define TracyQueuePrepareC( _type ) \
140     auto item = tracy::Profiler::QueueSerial(); \
141     tracy::MemWrite( &item->hdr.type, _type );
142 #  define TracyQueueCommitC( _name ) \
143     tracy::MemWrite( &item->_name.thread, tracy::GetThreadHandle() ); \
144     tracy::Profiler::QueueSerialFinish();
