147 #  define TracyQueueCommit( _name ) TracyLfqCommit
148 #  define TracyQueuePrepareC( _type ) TracyLfqPrepareC( _type )
149 #  define TracyQueueCommitC( _name ) TracyLfqCommitC
150 #endif
