190     static tracy_force_inline int64_t GetTime()
191     {
192 #ifdef TRACY_HW_TIMER
193 #  if defined TARGET_OS_IOS && TARGET_OS_IOS == 1
194         if( HardwareSupportsInvariantTSC() ) return mach_absolute_time();
195 #  elif defined _WIN32
196 #    ifdef TRACY_TIMER_QPC
197         return GetTimeQpc();
198 #    else
199         if( HardwareSupportsInvariantTSC() ) return int64_t( __rdtsc() );
200 #    endif
201 #  elif defined __i386 || defined _M_IX86
202         if( HardwareSupportsInvariantTSC() )
203         {
204             uint32_t eax, edx;
205             asm volatile ( "rdtsc" : "=a" (eax), "=d" (edx) );
206             return ( uint64_t( edx ) << 32 ) + uint64_t( eax );
207         }
208 #  elif defined __x86_64__ || defined _M_X64
209         if( HardwareSupportsInvariantTSC() )
210         {
211             uint64_t rax, rdx;
212 #ifdef TRACY_PATCHABLE_NOPSLEDS
213             // Some external tooling (such as rr) wants to patch our rdtsc and replace it by a
214             // branch to control the external input seen by a program. This kind of patching is
215             // not generally possible depending on the surrounding code and can lead to significant
216             // slowdowns if the compiler generated unlucky code and rr and tracy are used together.
217             // To avoid this, use the rr-safe `nopl 0(%rax, %rax, 1); rdtsc` instruction sequence,
218             // which rr promises will be patchable independent of the surrounding code.
219             asm volatile (
220                     // This is nopl 0(%rax, %rax, 1), but assemblers are inconsistent about whether
221                     // they emit that as a 4 or 5 byte sequence and we need to be guaranteed to use
222                     // the 5 byte one.
223                     ".byte 0x0f, 0x1f, 0x44, 0x00, 0x00\n\t"
224                     "rdtsc" : "=a" (rax), "=d" (rdx) );
225 #else
226             asm volatile ( "rdtsc" : "=a" (rax), "=d" (rdx) );
227 #endif
228             return (int64_t)(( rdx << 32 ) + rax);
229         }
230 #  else
231 #    error "TRACY_HW_TIMER detection logic needs fixing"
232 #  endif
233 #endif
234 
235 #if !defined TRACY_HW_TIMER || defined TRACY_TIMER_FALLBACK
236 #  if defined __linux__ && defined CLOCK_MONOTONIC_RAW
237         struct timespec ts;
238         clock_gettime( CLOCK_MONOTONIC_RAW, &ts );
239         return int64_t( ts.tv_sec ) * 1000000000ll + int64_t( ts.tv_nsec );
240 #  else
241         return std::chrono::duration_cast<std::chrono::nanoseconds>( std::chrono::high_resolution_clock::now().time_since_epoch() ).count();
242 #  endif
243 #endif
244 
245 #if !defined TRACY_TIMER_FALLBACK
246         return 0;  // unreachable branch
247 #endif
248     }
