262     static tracy_force_inline QueueItem* QueueSerialCallstack( void* ptr )
263     {
264         auto& p = GetProfiler();
265         p.m_serialLock.lock();
266         p.SendCallstackSerial( ptr );
267         return p.m_serialQueue.prepare_next();
