277     static tracy_force_inline void SendFrameMark( const char* name )
278     {
279         if( !name ) GetProfiler().m_frameCount.fetch_add( 1, std::memory_order_relaxed );
280 #ifdef TRACY_ON_DEMAND
281         if( !GetProfiler().IsConnected() ) return;
282 #endif
283         auto item = QueueSerial();
284         MemWrite( &item->hdr.type, QueueType::FrameMarkMsg );
285         MemWrite( &item->frameMark.time, GetTime() );
286         MemWrite( &item->frameMark.name, uint64_t( name ) );
287         QueueSerialFinish();
288     }
289 
290     static tracy_force_inline void SendFrameMark( const char* name, QueueType type )
291     {
292         assert( type == QueueType::FrameMarkMsgStart || type == QueueType::FrameMarkMsgEnd );
293 #ifdef TRACY_ON_DEMAND
294         if( !GetProfiler().IsConnected() ) return;
295 #endif
296         auto item = QueueSerial();
297         MemWrite( &item->hdr.type, type );
298         MemWrite( &item->frameMark.time, GetTime() );
299         MemWrite( &item->frameMark.name, uint64_t( name ) );
300         QueueSerialFinish();
301     }
