303     static tracy_force_inline void SendFrameImage( const void* image, uint16_t w, uint16_t h, uint8_t offset, bool flip )
304     {
305 #ifndef TRACY_NO_FRAME_IMAGE
306         auto& profiler = GetProfiler();
307         assert( profiler.m_frameCount.load( std::memory_order_relaxed ) < (std::numeric_limits<uint32_t>::max)() );
308 #  ifdef TRACY_ON_DEMAND
309         if( !profiler.IsConnected() ) return;
310 #  endif
311         const auto sz = size_t( w ) * size_t( h ) * 4;
312         auto ptr = (char*)tracy_malloc( sz );
313         memcpy( ptr, image, sz );
314 
315         profiler.m_fiLock.lock();
316         auto fi = profiler.m_fiQueue.prepare_next();
317         fi->image = ptr;
318         fi->frame = uint32_t( profiler.m_frameCount.load( std::memory_order_relaxed ) - offset );
319         fi->w = w;
320         fi->h = h;
321         fi->flip = flip;
322         profiler.m_fiQueue.commit_next();
323         profiler.m_fiLock.unlock();
324 #else
325         static_cast<void>(image); // unused
326         static_cast<void>(w); // unused
327         static_cast<void>(h); // unused
328         static_cast<void>(offset); // unused
329         static_cast<void>(flip); // unused
330 #endif
331     }
