385     static tracy_force_inline void Message( const char* txt, size_t size, int callstack )
386     {
387         assert( size < (std::numeric_limits<uint16_t>::max)() );
388 #ifdef TRACY_ON_DEMAND
389         if( !GetProfiler().IsConnected() ) return;
390 #endif
391         if( callstack != 0 )
392         {
393             tracy::GetProfiler().SendCallstack( callstack );
394         }
395 
396         auto ptr = (char*)tracy_malloc( size );
397         memcpy( ptr, txt, size );
398 
399         TracyQueuePrepare( callstack == 0 ? QueueType::Message : QueueType::MessageCallstack );
400         MemWrite( &item->messageFat.time, GetTime() );
401         MemWrite( &item->messageFat.text, (uint64_t)ptr );
402         MemWrite( &item->messageFat.size, (uint16_t)size );
403         TracyQueueCommit( messageFatThread );
404     }
