482     static tracy_force_inline void MemAlloc( const void* ptr, size_t size, bool secure )
483     {
484         if( secure && !ProfilerAvailable() ) return;
485 #ifdef TRACY_ON_DEMAND
486         if( !GetProfiler().IsConnected() ) return;
487 #endif
488         const auto thread = GetThreadHandle();
489 
490         GetProfiler().m_serialLock.lock();
491         SendMemAlloc( QueueType::MemAlloc, thread, ptr, size );
492         GetProfiler().m_serialLock.unlock();
493     }
494 
495     static tracy_force_inline void MemFree( const void* ptr, bool secure )
496     {
497         if( secure && !ProfilerAvailable() ) return;
498 #ifdef TRACY_ON_DEMAND
499         if( !GetProfiler().IsConnected() ) return;
500 #endif
501         const auto thread = GetThreadHandle();
502 
503         GetProfiler().m_serialLock.lock();
504         SendMemFree( QueueType::MemFree, thread, ptr );
505         GetProfiler().m_serialLock.unlock();
506     }
