508     static tracy_force_inline void MemAllocCallstack( const void* ptr, size_t size, int depth, bool secure )
509     {
510         if( secure && !ProfilerAvailable() ) return;
511 #ifdef TRACY_HAS_CALLSTACK
512         auto& profiler = GetProfiler();
513 #  ifdef TRACY_ON_DEMAND
514         if( !profiler.IsConnected() ) return;
515 #  endif
516         const auto thread = GetThreadHandle();
517 
518         auto callstack = Callstack( depth );
519 
520         profiler.m_serialLock.lock();
521         SendCallstackSerial( callstack );
522         SendMemAlloc( QueueType::MemAllocCallstack, thread, ptr, size );
523         profiler.m_serialLock.unlock();
524 #else
525         static_cast<void>(depth); // unused
526         MemAlloc( ptr, size, secure );
527 #endif
528     }
529 
530     static tracy_force_inline void MemFreeCallstack( const void* ptr, int depth, bool secure )
531     {
532         if( secure && !ProfilerAvailable() ) return;
533         if( !ProfilerAllocatorAvailable() )
534         {
535             MemFree( ptr, secure );
536             return;
537         }
538 #ifdef TRACY_HAS_CALLSTACK
539         auto& profiler = GetProfiler();
540 #  ifdef TRACY_ON_DEMAND
541         if( !profiler.IsConnected() ) return;
542 #  endif
543         const auto thread = GetThreadHandle();
544 
545         auto callstack = Callstack( depth );
546 
547         profiler.m_serialLock.lock();
548         SendCallstackSerial( callstack );
549         SendMemFree( QueueType::MemFreeCallstack, thread, ptr );
550         profiler.m_serialLock.unlock();
551 #else
552         static_cast<void>(depth); // unused
553         MemFree( ptr, secure );
554 #endif
555     }
