734     // Allocated source location data layout:
735     //  2b  payload size
736     //  4b  color
737     //  4b  source line
738     //  fsz function name
739     //  1b  null terminator
740     //  ssz source file name
741     //  1b  null terminator
742     //  nsz zone name (optional)
743 
744     static tracy_force_inline uint64_t AllocSourceLocation( uint32_t line, const char* source, const char* function )
745     {
746         return AllocSourceLocation( line, source, function, nullptr, 0 );
747     }
748 
749     static tracy_force_inline uint64_t AllocSourceLocation( uint32_t line, const char* source, const char* function, const char* name, size_t nameSz )
750     {
751         return AllocSourceLocation( line, source, strlen(source), function, strlen(function), name, nameSz );
752     }
753 
754     static tracy_force_inline uint64_t AllocSourceLocation( uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz )
755     {
756         return AllocSourceLocation( line, source, sourceSz, function, functionSz, nullptr, 0 );
757     }
758 
759     static tracy_force_inline uint64_t AllocSourceLocation( uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz, const char* name, size_t nameSz )
760     {
761         const auto sz32 = uint32_t( 2 + 4 + 4 + functionSz + 1 + sourceSz + 1 + nameSz );
762         assert( sz32 <= (std::numeric_limits<uint16_t>::max)() );
763         const auto sz = uint16_t( sz32 );
764         auto ptr = (char*)tracy_malloc( sz );
765         memcpy( ptr, &sz, 2 );
766         memset( ptr + 2, 0, 4 );
767         memcpy( ptr + 6, &line, 4 );
768         memcpy( ptr + 10, function, functionSz );
769         ptr[10 + functionSz] = '\0';
770         memcpy( ptr + 10 + functionSz + 1, source, sourceSz );
771         ptr[10 + functionSz + 1 + sourceSz] = '\0';
772         if( nameSz != 0 )
773         {
774             memcpy( ptr + 10 + functionSz + 1 + sourceSz + 1, name, nameSz );
775         }
776         return uint64_t( ptr );
777     }
