812     tracy_force_inline bool NeedDataSize( size_t len )
813     {
814         assert( len <= TargetFrameSize );
815         bool ret = true;
816         if( m_bufferOffset - m_bufferStart + (int)len > TargetFrameSize )
817         {
818             ret = CommitData();
819         }
820         return ret;
821     }
822 
823     tracy_force_inline void AppendDataUnsafe( const void* data, size_t len )
824     {
825         memcpy( m_buffer + m_bufferOffset, data, len );
826         m_bufferOffset += int( len );
827     }
