868     static tracy_force_inline void SendMemAlloc( QueueType type, const uint32_t thread, const void* ptr, size_t size )
869     {
870         assert( type == QueueType::MemAlloc || type == QueueType::MemAllocCallstack || type == QueueType::MemAllocNamed || type == QueueType::MemAllocCallstackNamed );
871 
872         auto item = GetProfiler().m_serialQueue.prepare_next();
873         MemWrite( &item->hdr.type, type );
874         MemWrite( &item->memAlloc.time, GetTime() );
875         MemWrite( &item->memAlloc.thread, thread );
876         MemWrite( &item->memAlloc.ptr, (uint64_t)ptr );
877         if( compile_time_condition<sizeof( size ) == 4>::value )
878         {
879             memcpy( &item->memAlloc.size, &size, 4 );
880             memset( &item->memAlloc.size + 4, 0, 2 );
881         }
882         else
883         {
884             assert( sizeof( size ) == 8 );
885             memcpy( &item->memAlloc.size, &size, 4 );
886             memcpy( ((char*)&item->memAlloc.size)+4, ((char*)&size)+4, 2 );
887         }
888         GetProfiler().m_serialQueue.commit_next();
889     }
890 
891     static tracy_force_inline void SendMemFree( QueueType type, const uint32_t thread, const void* ptr )
892     {
893         assert( type == QueueType::MemFree || type == QueueType::MemFreeCallstack || type == QueueType::MemFreeNamed || type == QueueType::MemFreeCallstackNamed );
894 
895         auto item = GetProfiler().m_serialQueue.prepare_next();
896         MemWrite( &item->hdr.type, type );
897         MemWrite( &item->memFree.time, GetTime() );
898         MemWrite( &item->memFree.thread, thread );
899         MemWrite( &item->memFree.ptr, (uint64_t)ptr );
900         GetProfiler().m_serialQueue.commit_next();
901     }
